ript>window.OPERATIONS_CONFIG={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,userId:<?=(int)$user['id']?>,canTasksView:<?=$canTasksView?'true':'false'?>,canTasksManage:<?=$canTasksManage?'true':'false'?>,canTasksSelf:<?=$canTasksSelf?'true':'false'?>,canTasksProof:<?=$canTasksProof?'true':'false'?>,canInventoryView:<?=$canInventoryView?'true':'false'?>,canInventoryManage:<?=$canInventoryManage?'true':'false'?>,canAgent:<?=$canAgent?'true':'false'?>};</script><script src="js/operations-core.js?v=20260913-2"></script><script src="js/universal-admin-page-shell.js?v=20260915-1"></script>
